var server,needle=require("../"),should=require("should"),http=require("http"),port=11112;describe("socket reuse",function(){var e=new http.Agent({keepAlive:!0,maxSockets:1});before(function(e){server=http.createServer(function(e,t){t.setHeader("Content-Type","application/json"),setTimeout(function(){t.end('{"foo":"bar"}')},50)}).listen(port,e)}),after(function(t){e.destroy(),server.close(t)}),describe("when sockets are reused",function(){it("does not duplicate listeners on .end",function(t){var o,r=10;function n(){needle.get("localhost:"+port,{agent:e},function(n,s){if(n)throw new Error("Unexpected error: "+n);for(hostTarget in e.sockets)e.sockets[hostTarget].forEach(function(e){try{e.listeners("end").length.should.be.below(5,"too many listeners on the socket object's end event")}catch(e){o=e}});--r||t(o)})}for(var s=0;s<r;s++)n()})})});